// Define the schema for the Studio page contract
const studioPageContractSchema = {
  type: 'object',
  properties: {
    title: { type: 'string' },
    description: { type: 'string' },
    sections: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          content: { type: 'string' }
        },
        required: ['title', 'content']
      }
    }
  },
  required: ['title', 'description', 'sections']
};

module.exports = studioPageContractSchema;

// Import the schema for the Studio page contract
const studioPageContractSchema = require('../src/studio_page_contract.mjs');

// Test the schema
const Ajv = require('ajv');
const ajv = new Ajv();
const validate = ajv.compile(studioPageContractSchema);

// Sample data to validate
const sampleData = {
  title: 'Sample Studio Page',
  description: 'This is a sample studio page.',
  sections: [
    { title: 'Section 1', content: 'Content for section 1.' },
    { title: 'Section 2', content: 'Content for section 2.' }
  ]
};

// Run the validation
const isValid = validate(sampleData);

// Assert the result
if (isValid) {
  console.log('Schema is valid.');
} else {
  console.error('Schema is invalid:', validate.errors);
}

